--
-- Table structure for table `activity_feed`
--

DROP TABLE IF EXISTS `activity_feed`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `activity_feed` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `activity_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `scope` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'organization',
  `actor_id` int unsigned DEFAULT NULL,
  `organization_id` int unsigned DEFAULT NULL,
  `company_id` int unsigned DEFAULT NULL,
  `department_id` int unsigned DEFAULT NULL,
  `asset_id` int unsigned DEFAULT NULL,
  `employee_id` int unsigned DEFAULT NULL,
  `module` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `action` varchar(96) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `summary` text COLLATE utf8mb4_unicode_ci,
  `event_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `correlation_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `related_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `meta` json DEFAULT NULL,
  `occurred_at` datetime NOT NULL,
