INSERT INTO `allocations` VALUES (1,'ALC-2026-00001','single','returned',2,1,NULL,NULL,1,NULL,NULL,1,4,NULL,NULL,0,0,1,NULL,NULL,NULL,'By accepting this allocation you confirm:\n1. You received the listed asset(s) in working condition.\n2. You will use the asset(s) for authorized business purposes only.\n3. You will report loss, damage, or theft immediately.\n4. You will return the asset(s) on request or at end of assignment.\n5. Company ownership of the asset(s) remains with Refex.','verify complete',NULL,NULL,NULL,NULL,'2026-08-06 13:53:37','2026-08-06 13:53:37',NULL,'2026-08-06 13:53:50','2026-08-06 13:53:50',NULL,'2026-08-06 13:53:37','2026-08-06 13:53:50',NULL),(2,'ALC-2026-00002','temporary','in_use',1,1,NULL,NULL,1,NULL,NULL,2,1,'Pilot',NULL,1,0,1,NULL,NULL,'2026-12-31 00:00:00','By accepting this allocation you confirm:\n1. You received the listed asset(s) in working condition.\n2. You will use the asset(s) for authorized business purposes only.\n3. You will report loss, damage, or theft immediately.\n4. You will return the asset(s) on request or at end of assignment.\n5. Company ownership of the asset(s) remains with Refex.',NULL,NULL,NULL,NULL,NULL,'2026-08-06 13:53:59','2026-08-06 13:53:59','2026-08-06 13:53:59',NULL,NULL,NULL,'2026-08-06 13:53:59','2026-08-06 13:53:59',NULL);
