--
-- Table structure for table `platform_events`
--

DROP TABLE IF EXISTS `platform_events`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `platform_events` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `event_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `event_type` varchar(96) COLLATE utf8mb4_unicode_ci NOT NULL,
  `occurred_at` datetime NOT NULL,
  `actor_id` int unsigned DEFAULT NULL,
  `organization_id` int unsigned DEFAULT NULL,
  `company_id` int unsigned DEFAULT NULL,
  `asset_id` int unsigned DEFAULT NULL,
  `employee_id` int unsigned DEFAULT NULL,
  `workflow_instance_id` bigint unsigned DEFAULT NULL,
  `correlation_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `module` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `subject_type` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `subject_id` bigint unsigned DEFAULT NULL,
  `payload` json DEFAULT NULL,
  `metadata` json DEFAULT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'published',
  `retry_count` int NOT NULL DEFAULT '0',
  `dead_lettered_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_platform_event_id` (`event_id`),
  KEY `idx_pe_type_time` (`event_type`,`occurred_at`),
  KEY `idx_pe_corr` (`correlation_id`),
  KEY `idx_pe_asset` (`asset_id`),
  KEY `idx_pe_actor` (`actor_id`),
  KEY `idx_pe_org` (`organization_id`),
  KEY `idx_pe_wf` (`workflow_instance_id`),
  KEY `idx_pe_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `platform_events`
--

