INSERT INTO `workflow_definitions` VALUES (1,'allocation','Asset Allocation','Reusable allocation workflow template for future orchestration','allocation',1,1,1,'{\"states\": [\"requested\", \"pending_approval\", \"approved\", \"reserved\", \"allocated\", \"in_use\", \"return_requested\", \"returned\", \"rejected\", \"cancelled\"], \"initial\": \"requested\", \"terminal\": [\"returned\", \"rejected\", \"cancelled\"], \"approvals\": {\"mode\": \"single\", \"steps\": [{\"key\": \"manager\", \"role\": \"manager\"}]}, \"transitions\": [{\"to\": \"pending_approval\", \"key\": \"submit\", \"from\": \"requested\"}, {\"to\": \"approved\", \"key\": \"approve\", \"from\": \"pending_approval\", \"requires_approval\": true}, {\"to\": \"reserved\", \"key\": \"reserve\", \"from\": \"approved\"}, {\"to\": \"allocated\", \"key\": \"allocate\", \"from\": \"reserved\"}, {\"to\": \"in_use\", \"key\": \"accept\", \"from\": \"allocated\"}, {\"to\": \"return_requested\", \"key\": \"request_return\", \"from\": \"in_use\"}, {\"to\": \"returned\", \"key\": \"complete_return\", \"from\": \"return_requested\"}, {\"to\": \"rejected\", \"key\": \"reject\", \"from\": \"pending_approval\"}, {\"to\": \"cancelled\", \"key\": \"cancel\", \"from\": \"requested\"}], \"audit_events\": [\"allocation.requested\", \"allocation.approved\", \"allocation.rejected\", \"allocation.returned\"], \"notifications\": [\"allocation.requested\", \"allocation.approved\", \"allocation.allocated\"], \"business_rules\": [\"asset_must_be_available\", \"employee_must_be_active\"], \"timeline_events\": [\"allocation.requested\", \"allocation.approved\", \"allocation.allocated\", \"allocation.accepted\", \"allocation.returned\"]}',NULL,'2026-08-07 10:02:47','2026-08-07 10:02:47',NULL),(2,'transfer','Asset Transfer','Template for future Transfer module','transfer',1,1,1,'{\"states\": [\"requested\", \"pending_approval\", \"approved\", \"in_transit\", \"completed\", \"cancelled\"], \"initial\": \"requested\", \"terminal\": [\"completed\", \"cancelled\"], \"approvals\": {\"mode\": \"sequential\", \"steps\": [{\"key\": \"source_manager\"}, {\"key\": \"dest_manager\"}]}, \"transitions\": [{\"to\": \"pending_approval\", \"key\": \"submit\", \"from\": \"requested\"}, {\"to\": \"approved\", \"key\": \"approve\", \"from\": \"pending_approval\", \"requires_approval\": true}, {\"to\": \"in_transit\", \"key\": \"ship\", \"from\": \"approved\"}, {\"to\": \"completed\", \"key\": \"complete\", \"from\": \"in_transit\"}, {\"to\": \"cancelled\", \"key\": \"cancel\", \"from\": \"requested\"}], \"audit_events\": [\"transfer.requested\", \"transfer.completed\"], \"notifications\": [\"transfer.requested\", \"transfer.completed\"], \"business_rules\": [\"employee_must_be_active\", \"department_must_exist\"], \"timeline_events\": [\"transfer.requested\", \"transfer.completed\"]}',NULL,'2026-08-07 10:02:47','2026-08-07 10:02:47',NULL),(3,'return','Asset Return','Template for future Return module','return',1,1,1,'{\"states\": [\"requested\", \"pending_inspection\", \"completed\", \"cancelled\"], \"initial\": \"requested\", \"terminal\": [\"completed\", \"cancelled\"], \"approvals\": {\"mode\": \"single\", \"steps\": []}, \"transitions\": [{\"to\": \"pending_inspection\", \"key\": \"submit\", \"from\": \"requested\"}, {\"to\": \"completed\", \"key\": \"complete\", \"from\": \"pending_inspection\"}, {\"to\": \"cancelled\", \"key\": \"cancel\", \"from\": \"requested\"}], \"audit_events\": [\"return.requested\", \"return.completed\"], \"notifications\": [\"return.requested\", \"return.completed\"], \"business_rules\": [\"employee_must_be_active\"], \"timeline_events\": [\"return.requested\", \"return.completed\"]}',NULL,'2026-08-07 10:02:47','2026-08-07 10:02:47',NULL),(4,'maintenance','Maintenance','Template for future Maintenance module','maintenance',1,1,1,'{\"states\": [\"requested\", \"approved\", \"in_progress\", \"completed\", \"cancelled\"], \"initial\": \"requested\", \"terminal\": [\"completed\", \"cance